window.axios = (() => {
	async function executeFetch(method, url, payload = null, config = {}) {
		const fetchOptions = { method, ...config, headers: { ...config.headers } };

		if (payload) {
			if (payload instanceof FormData) {
				fetchOptions.body = payload;
			} else {
				fetchOptions.body = JSON.stringify(payload);
				fetchOptions.headers["Content-Type"] = "application/json";
			}
		}

		const response = await fetch(url, fetchOptions);

		if (!response.ok) {
			const error = new Error(
				response.statusText || "Network response was not ok",
			);
			error.response = response;
			throw error;
		}

		let parsedData;
		if (config.responseType === "blob") {
			parsedData = await response.blob();
		} else {
			const rawText = await response.text();
			try {
				parsedData = rawText ? JSON.parse(rawText) : {};
			} catch {
				parsedData = rawText;
			}
		}

		return {
			data: parsedData,
			status: response.status,
			statusText: response.statusText,
			headers: response.headers,
		};
	}

	return {
		get: (url, config) => executeFetch("GET", url, null, config),
		post: (url, payload, config) => executeFetch("POST", url, payload, config),
		put: (url, payload, config) => executeFetch("PUT", url, payload, config),
	};
})();
